    50	      {
    51	        type: 'section',
    52	        text: {
    53	          type: 'mrkdwn',
    54	          text: formatted.body
    55	        }
    56	      },
    57	      {
    58	        type: 'context',
    59	        elements: [
    60	          {
    61	            type: 'mrkdwn',
    62	            text: `Category: ${formatted.metadata.category}`
    63	          }
    64	        ]
    65	      }
    66	    ];
    67	  }
    68	
    69	  async deliver(payload) {
    70	    if (typeof this.transport.slack !== 'function') {
    71	      throw new Error('slack transport is not configured');
