const HOUR_MS = 60 * 60 * 1000;
const NOT_THROTTLED = Object.freeze({ throttled: false });

/**
 * Runs throttle rules in order. Each rule receives the send context
 * `{ notifier, user, message, options }` and returns a decision to stop
 * evaluation, or null to defer to the next rule.
 */
function evaluateThrottle(rules, context) {
  for (const rule of rules) {
    const decision = rule(context);
    if (decision) {
      return decision;
    }
  }
  return NOT_THROTTLED;
}

// Forced and urgent sends skip the hourly cap but still reach later rules,
// such as the marketing opt-in check.
function hourlyLimit({ notifier, user, message, options }) {
  if (options.force || message.priority === 'urgent') {
    return null;
  }

  const key = throttleKey(notifier.channel, user, message);
  const now = notifier.now().getTime();
  const records = (notifier.throttleStore.get(key) || []).filter(ts => now - ts < HOUR_MS);

  if (records.length >= notifier.maxPerHour) {
    return {
      throttled: true,
      reason: `${notifier.channel} hourly limit reached`,
      retryAt: new Date(records[0] + HOUR_MS).toISOString()
    };
  }

  return null;
}

function exemptWhen(predicate) {
  return context => (predicate(context) ? NOT_THROTTLED : null);
}

function requireMarketingOptIn(optInField, reason) {
  return ({ user, message }) => {
    if (message.category === 'marketing' && !user[optInField]) {
      return { throttled: true, reason, retryAt: null };
    }
    return null;
  };
}

function recordDelivery({ notifier, user, message }) {
  const key = throttleKey(notifier.channel, user, message);
  const records = notifier.throttleStore.get(key) || [];
  records.push(notifier.now().getTime());
  notifier.throttleStore.set(key, records);
}

function throttleKey(channel, user, message) {
  const category = message.category || 'general';
  return `${channel}:${user.id}:${category}`;
}

module.exports = {
  evaluateThrottle,
  hourlyLimit,
  exemptWhen,
  requireMarketingOptIn,
  recordDelivery
};

