const { createChannelNotifier, deliverVia } = require('./channelNotifier');
const { hourlyLimit, requireMarketingOptIn } = require('./throttling');

const PREVIEW_LENGTH = 90;

const emailChannel = {
  channel: 'email',
  defaults: {
    maxPerHour: 8,
    from: 'noreply@example.com',
    replyTo: 'support@example.com',
    unsubscribeBaseUrl: 'https://example.com/unsubscribe'
  },

  validateUser(user) {
    if (!user.email || !user.email.includes('@')) {
      throw new TypeError('user.email is required for email notifications');
    }
  },

  throttleRules: [
    hourlyLimit,
    requireMarketingOptIn('emailOptIn', 'user has not opted into marketing email')
  ],

  format(base, { notifier, user, message }) {
    const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
    const footer = footerFor(notifier, user, message);

    return {
      to: user.email,
      from: notifier.from,
      replyTo: notifier.replyTo,
      subject: `${subjectPrefix}${base.title}`,
      text: `${base.body}\n\n${footer}`,
      html: `<h1>${escapeHtml(base.title)}</h1><p>${escapeHtml(base.body)}</p><footer>${escapeHtml(footer)}</footer>`,
      preview: base.body.slice(0, PREVIEW_LENGTH)
    };
  },

  deliver: deliverVia('email')
};

function footerFor(notifier, user, message) {
  if (message.category === 'transactional' || message.category === 'security') {
    return `Sent to ${user.email} because of recent account activity.`;
  }
  const url = `${notifier.unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
  return `You can unsubscribe at ${url}.`;
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function createEmailNotifier(options = {}) {
  return createChannelNotifier(emailChannel, options);
}

module.exports = createEmailNotifier;

