    const composed = `${prefix}${base.title} - ${base.body}`;
    const text = truncate(composed, notifier.segmentLength);

    return {
      to: user.phone,
      from: notifier.senderId,
      text,
      segments: Math.ceil(text.length / notifier.segmentLength),
      preview: text
    };
