const { createChannelNotifier, deliverVia } = require('./channelNotifier');
const { exemptWhen, hourlyLimit } = require('./throttling');

const PREVIEW_LENGTH = 120;

const slackChannel = {
  channel: 'slack',
  defaults: {
    maxPerHour: 20,
    defaultWorkspace: 'main',
    defaultChannel: '#general'
  },

  validateUser(user) {
    if (!user.slackId && !user.slackChannel) {
      throw new TypeError('user.slackId or user.slackChannel is required for Slack notifications');
    }
  },

  throttleRules: [
    exemptWhen(({ options }) => Boolean(options.threadTs)),
    hourlyLimit
  ],

  format(base, { notifier, user, options }) {
    const channel = options.channel || user.slackChannel || notifier.defaultChannel;
    const mention = user.slackId ? `<@${user.slackId}> ` : '';
    const text = `${mention}*${base.title}*\n${base.body}`;

    return {
      workspace: user.slackWorkspace || notifier.defaultWorkspace,
      channel,
      threadTs: options.threadTs || null,
      text,
      blocks: blocksFor(base, mention),
      preview: text.replace(/\*/g, '').slice(0, PREVIEW_LENGTH)
    };
  },

  deliver: deliverVia('slack')
};

function blocksFor(base, mention) {
  return [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `${mention}*${base.title}*`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: base.body
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `Category: ${base.metadata.category}`
        }
      ]
    }
  ];
}

function createSlackNotifier(options = {}) {
  return createChannelNotifier(slackChannel, options);
}

module.exports = createSlackNotifier;

