const { createChannelNotifier, deliverVia } = require('./channelNotifier');
const { exemptWhen, hourlyLimit } = require('./throttling');

const URGENT_EXPIRY_HOURS = 72;
const DEFAULT_EXPIRY_HOURS = 168;

const inAppChannel = {
  channel: 'inapp',
  defaults: {
    maxPerHour: 50,
    defaultIcon: 'bell',
    defaultAction: '/notifications'
  },

  validateUser(user) {
    if (user.disabledInApp) {
      throw new TypeError('in-app notifications are disabled for this user');
    }
  },

  throttleRules: [
    exemptWhen(({ message }) => message.category === 'security'),
    hourlyLimit
  ],

  format(base, { notifier, user, message, options }) {
    const expiresInHours =
      options.expiresInHours || (message.priority === 'urgent' ? URGENT_EXPIRY_HOURS : DEFAULT_EXPIRY_HOURS);
    // Same multiplication order as before, so fractional hours round to the same millisecond.
    const expiresAt = new Date(notifier.now().getTime() + expiresInHours * 60 * 60 * 1000);

    return {
      userId: user.id,
      icon: message.icon || notifier.defaultIcon,
      actionUrl: options.actionUrl || message.actionUrl || notifier.defaultAction,
      read: false,
      expiresAt: expiresAt.toISOString(),
      preview: base.title
    };
  },

  deliver: deliverVia('inapp', 'in-app')
};

function createInAppNotifier(options = {}) {
  return createChannelNotifier(inAppChannel, options);
}

module.exports = createInAppNotifier;

