// Differential check: original class hierarchy vs refactored composition.
const assert = require('node:assert/strict');
const path = require('node:path');

const original = require('./original/index.js');
const refactored = require(path.resolve(process.argv[2], 'src/notifications/index.js'));

let seed = 20260930;
function rand() {
  seed = (seed * 1103515245 + 12345) % 2147483648;
  return seed / 2147483648;
}
const pick = list => list[Math.floor(rand() * list.length)];

function steppingClock(start = Date.parse('2026-01-02T03:04:05.000Z'), step = 1234) {
  const clock = { calls: 0 };
  clock.now = () => new Date(start + step * clock.calls++);
  return clock;
}

function makeTransport(kind, log) {
  const record = channel => async function (payload) {
    log.push([channel, JSON.stringify(payload), this === transport]);
    if (kind === 'mutating') payload.preview = 'mutated';
    if (kind === 'failing') throw new Error(`${channel} upstream down`);
  };
  const transport = {};
  if (kind === 'none') return undefined;
  if (kind === 'nonFunction') return { email: 'x', sms: 1, slack: {}, inapp: null };
  for (const channel of ['email', 'sms', 'slack', 'inapp']) transport[channel] = record(channel);
  return transport;
}

function describeOutcome(fn) {
  return fn().then(
    value => ({ ok: value }),
    error => ({ error: { name: error.constructor.name, message: error.message } })
  );
}

function snapshotStore(store) {
  return [...store.entries()].map(([k, v]) => [k, [...v]]);
}

function publicConfig(notifier, dropped) {
  const out = {};
  for (const [key, value] of Object.entries(notifier)) {
    if (dropped.includes(key)) continue;
    out[key] = typeof value === 'function' ? 'fn' : value instanceof Map ? 'Map' : value;
  }
  return out;
}

async function runScenario(lib, scenario) {
  const clock = steppingClock();
  const log = [];
  const throttleStore = new Map(scenario.preload.map(([k, v]) => [k, [...v]]));
  const factoryOptions = {
    ...scenario.factoryOptions,
    transport: makeTransport(scenario.transportKind, log),
    throttleStore,
    now: scenario.useDefaultClock ? undefined : clock.now
  };
  const notifier = lib.createNotifier(scenario.channel, factoryOptions);
  const outcomes = [];
  for (let i = 0; i < scenario.repeats; i++) {
    outcomes.push(await describeOutcome(() =>
      scenario.sendOptions === undefined
        ? notifier.send(scenario.user, scenario.message)
        : notifier.send(scenario.user, scenario.message, scenario.sendOptions)
    ));
  }
  return {
    outcomes: scenario.useDefaultClock ? outcomes.map(stripTimes) : outcomes,
    log: scenario.useDefaultClock ? log.length : log,
    store: scenario.useDefaultClock ? throttleStore.size : snapshotStore(throttleStore),
    nowCalls: clock.calls,
    config: publicConfig(notifier, ['templates', 'defaultSender', 'send'])
  };
}

function stripTimes(outcome) {
  if (!outcome.ok) return outcome;
  const { id, retryAt, ...rest } = outcome.ok;
  return { ok: { ...rest, hasId: id !== undefined, retryAt: retryAt === null ? null : typeof retryAt } };
}

const channels = ['email', 'sms', 'slack', 'inapp'];
const users = [
  { id: 'u1', name: 'Ava', email: 'ava@example.com', phone: '+15551234567', slackId: 'U1', emailOptIn: true, smsOptIn: true },
  { id: 'u2', email: 'bo@example.com', phone: '+447911123456', slackChannel: '#alerts', locale: 'fr-FR' },
  { id: 'ü/ß &?', name: '$& <b>"x"</b>', email: 'weird@example.com', phone: '+33123456789', slackId: 'U9', slackWorkspace: 'eng' },
  { id: 7, name: 'Num', email: 'n@example.com', phone: '+12025550123', slackChannel: '#c', emailOptIn: false, smsOptIn: false },
  { id: 'u5', email: 'no-at-sign', phone: '555-1212' },
  { id: 'u6', email: 12345, phone: 15551234567 },
  { id: 'u7', disabledInApp: true, email: 'd@example.com', phone: '+15551234567', slackId: 'U7' },
  { id: '', email: 'e@example.com' },
  { name: 'no id' },
  null,
  'string-user',
  undefined
];
const messages = [
  { title: 'Hello {{name}}', body: 'Your {{category}} for {{id}} is ready', category: 'transactional' },
  { title: 'Deal', body: 'Save now', category: 'marketing' },
  { title: 'Login', body: '<script>alert("x") & more</script>', category: 'security' },
  { title: 'Deploy', body: 'Finished', category: 'release', icon: 'rocket', actionUrl: '/deploys' },
  { title: 'A'.repeat(200), body: 'B'.repeat(300), priority: 'urgent' },
  { title: 'Plain', body: 'No category' },
  { title: 'Ünïcødé 🎉', body: '日本語のメッセージ 😀'.repeat(20), category: 'general', priority: 'normal' },
  { title: 'Urgent deal', body: 'Now', category: 'marketing', priority: 'urgent' },
  { title: '', body: 'missing title' },
  { title: 'missing body' },
  null,
  'string-message'
];
const sendOptionsPool = [
  undefined,
  {},
  { force: true },
  { locale: 'de-DE' },
  { channel: '#ops', threadTs: '171234.0001' },
  { threadTs: '1.2' },
  { actionUrl: '/security', expiresInHours: 5 },
  { expiresInHours: 0.001 },
  { expiresInHours: 0 },
  { channel: '#override' }
];
const factoryOptionsPool = [
  {},
  { maxPerHour: 1 },
  { maxPerHour: 0 },
  { maxPerHour: 2, defaultLocale: 'es-ES' },
  { from: 'alerts@example.com', replyTo: 'help@example.com', unsubscribeBaseUrl: 'https://x.test/u' },
  { segmentLength: 40, senderId: 'ACME' },
  { segmentLength: 1 },
  { defaultWorkspace: 'product', defaultChannel: '#team' },
  { defaultIcon: 'star', defaultAction: '/inbox', channel: 'ignored' },
  { templates: { a: 1 }, defaultSender: 'Someone' }
];
const transportKinds = ['logging', 'logging', 'logging', 'mutating', 'failing', 'none', 'nonFunction'];

function randomScenario() {
  const channel = pick(channels);
  const user = pick(users);
  const message = pick(messages);
  const preload = rand() < 0.3 && user && typeof user === 'object' && user.id
    ? [[`${channel}:${user.id}:${(message && message.category) || 'general'}`,
        [Date.parse('2026-01-02T02:30:00.000Z'), Date.parse('2026-01-02T01:00:00.000Z'), Date.parse('2026-01-02T03:00:00.000Z')]]]
    : [];
  return {
    channel,
    user,
    message,
    sendOptions: pick(sendOptionsPool),
    factoryOptions: pick(factoryOptionsPool),
    transportKind: pick(transportKinds),
    repeats: 1 + Math.floor(rand() * 4),
    preload,
    useDefaultClock: rand() < 0.05
  };
}

async function compare(scenario, label) {
  const before = await runScenario(original, scenario);
  const after = await runScenario(refactored, scenario);
  try {
    assert.deepStrictEqual(after, before);
  } catch (error) {
    console.error(`MISMATCH in ${label}:`, JSON.stringify(scenario, null, 2));
    throw error;
  }
  return before;
}

async function main() {
  const tally = { sent: 0, throttled: 0, errors: new Map() };
  const iterations = Number(process.argv[3] || 5000);
  for (let i = 0; i < iterations; i++) {
    const before = await compare(randomScenario(), `random #${i}`);
    for (const outcome of before.outcomes) {
      if (outcome.error) tally.errors.set(outcome.error.message, (tally.errors.get(outcome.error.message) || 0) + 1);
      else tally[outcome.ok.status]++;
    }
  }

  // Exhaustive pass over every channel x message x send option for a valid user.
  let exhaustive = 0;
  for (const channel of channels) {
    for (const message of messages) {
      for (const sendOptions of sendOptionsPool) {
        for (const factoryOptions of factoryOptionsPool) {
          await compare({ channel, user: users[0], message, sendOptions, factoryOptions, transportKind: 'logging', repeats: 3, preload: [], useDefaultClock: false }, `exhaustive ${channel}`);
          exhaustive++;
        }
      }
    }
  }

  // Factory surface.
  assert.deepEqual(Object.keys(refactored.registry), Object.keys(original.registry));
  assert.deepEqual(Object.keys(refactored.createAllNotifiers({})), Object.keys(original.createAllNotifiers({})));
  for (const bad of ['fax', '', undefined, null, 42, 'EMAIL']) {
    assert.throws(() => original.createNotifier(bad), { name: 'TypeError', message: `unknown notification channel: ${bad}` });
    assert.throws(() => refactored.createNotifier(bad), { name: 'TypeError', message: `unknown notification channel: ${bad}` });
  }
  for (const protoKey of ['toString', 'constructor', '__proto__', 'hasOwnProperty']) {
    assert.throws(() => refactored.createNotifier(protoKey), { name: 'TypeError', message: `unknown notification channel: ${protoKey}` });
  }
  // createAllNotifiers without a shared store gives each channel its own Map and transport.
  const all = refactored.createAllNotifiers({});
  assert.notEqual(all.email.throttleStore, all.sms.throttleStore);
  assert.notEqual(all.email.transport, all.sms.transport);
  // Deep importers that did `new EmailNotifier(options)` still get a working notifier.
  const EmailNotifier = require(path.resolve(process.argv[2], 'src/notifications/EmailNotifier.js'));
  const log = [];
  const viaNew = new EmailNotifier({ transport: { email: async p => log.push(p) } });
  assert.equal((await viaNew.send({ id: 'x', email: 'x@example.com' }, { title: 't', body: 'b' })).status, 'sent');
  // A detached send works (it threw on the class because `this` was lost).
  const { send } = refactored.createNotifier('inapp', { transport: { inapp: async () => {} } });
  assert.equal((await send({ id: 'd' }, { title: 't', body: 'b' })).status, 'sent');
  // Reassigning config after creation still takes effect, as with class fields.
  const mutable = refactored.createNotifier('sms', { transport: { sms: async () => {} }, maxPerHour: 5 });
  mutable.maxPerHour = 1;
  await mutable.send({ id: 'm', phone: '+15551234567' }, { title: 't', body: 'b' });
  assert.equal((await mutable.send({ id: 'm', phone: '+15551234567' }, { title: 't', body: 'b' })).status, 'throttled');

  console.log(`random scenarios: ${iterations}, exhaustive scenarios: ${exhaustive}`);
  console.log(`outcomes covered: sent=${tally.sent} throttled=${tally.throttled}`);
  console.log('errors covered:', Object.fromEntries(tally.errors));
  console.log('OK: refactored implementation matches the original');
}

main().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

