const rand = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
const pick = list => list[Math.floor(rand() * list.length)];

function makeClock(start = Date.parse('2026-01-02T03:04:05.000Z'), step = 1234) {
  const clock = { calls: 0 };
  clock.now = () => new Date(start + step * clock.calls++);
  return clock;
}

function makeTransport(kind, log) {
  if (kind === 'none') return undefined;
  if (kind === 'nonFunction') return { email: 'x', sms: 1, slack: {}, inapp: null };
  const transport = {};
  for (const channel of ['email', 'sms', 'slack', 'inapp']) {
    transport[channel] = async function (payload) {
      log.push([channel, JSON.stringify(payload), this === transport]);
      if (kind === 'mutating') payload.preview = 'mutated';
      if (kind === 'failing') throw new Error(`${channel} upstream down`);
    };
  }
  return transport;
}

const outcome = promise => promise.then(
  ok => ({ ok }),
  error => ({ error: { name: error.constructor.name, message: error.message } })
);

function config(notifier, passed) {
  const out = {};
  for (const [key, value] of Object.entries(notifier)) {
    if (['templates', 'defaultSender', 'send'].includes(key)) continue;
    if (['transport', 'throttleStore', 'now'].includes(key)) {
      out[key] = value === passed[key] ? 'as passed' : typeof value === 'function' ? 'default fn' : JSON.stringify(value);
    } else {
      out[key] = value;
    }
  }
  return out;
}

function stripTimes(result) {
  if (!result.ok) return result;
  const { id, retryAt, ...rest } = result.ok;
  return { ok: { ...rest, hasId: id !== undefined, retryAt: retryAt === null ? null : typeof retryAt } };
}

async function run(lib, s) {
  const clock = makeClock(s.clockStart, s.clockStart === 0 ? 0 : undefined);
  const log = [];
  const throttleStore = new Map(s.preload.map(([k, v]) => [k, [...v]]));
  const options = { ...s.factoryOptions, transport: makeTransport(s.transportKind, log), throttleStore, now: s.realClock ? undefined : clock.now };
  const notifier = lib.createNotifier(s.channel, options);
  const outcomes = [];
  for (let i = 0; i < s.repeats; i++) {
    // Sequential on purpose: each send must observe the previous send's throttle record.
    outcomes.push(await outcome(s.sendOptions === undefined
      ? notifier.send(s.user, s.message)
      : notifier.send(s.user, s.message, s.sendOptions)));
  }
  return {
    outcomes: s.realClock ? outcomes.map(stripTimes) : outcomes,
    log: s.realClock ? log.length : log,
    store: s.realClock ? throttleStore.size : [...throttleStore].map(([k, v]) => [k, [...v]]),
    nowCalls: clock.calls,
    config: config(notifier, options)
  };
}

const channels = ['email', 'sms', 'slack', 'inapp'];
const users = [
  { id: 'u1', name: 'Ava', email: 'ava@example.com', phone: '+15551234567', slackId: 'U1', emailOptIn: true, smsOptIn: true },
  { id: 'u2', email: 'bo@example.com', phone: '+447911123456', slackChannel: '#alerts', locale: 'fr-FR' },
  { id: 'ü/ß &?', name: '$& <b>"x"</b>', email: 'weird@example.com', phone: '+33123456789', slackId: 'U9', slackWorkspace: 'eng' },
  { id: 7, name: 'Num', email: 'n@example.com', phone: '+12025550123', slackChannel: '#c', emailOptIn: false, smsOptIn: false },
  { id: 'u5', email: 'no-at-sign', phone: '555-1212' },
  { id: 'u6', email: 12345, phone: 15551234567 },
  { id: 'u7', disabledInApp: true, email: 'd@example.com', phone: '+15551234567', slackId: 'U7' },
  { id: '', email: 'e@example.com' },
  { name: 'no id' },
  null,
  'string-user',
  undefined
];
const messages = [
  { title: 'Hello {{name}}', body: 'Your {{category}} for {{id}} is ready', category: 'transactional' },
  { title: 'Deal', body: 'Save now', category: 'marketing' },
  { title: 'Login', body: '<script>alert("x") & more</script>', category: 'security' },
  { title: 'Deploy', body: 'Finished', category: 'release', icon: 'rocket', actionUrl: '/deploys' },
  { title: 'A'.repeat(200), body: 'B'.repeat(300), priority: 'urgent' },
  { title: 'Plain', body: 'No category' },
  { title: 'Ünïcødé 🎉', body: '日本語のメッセージ 😀'.repeat(20), category: 'general', priority: 'normal' },
  { title: 'Urgent deal', body: 'Now', category: 'marketing', priority: 'urgent' },
  { title: '', body: 'missing title' },
  { title: 'missing body' },
  null,
  'string-message'
];
const sendOptionsPool = [
  undefined, {}, { force: true }, { locale: 'de-DE' }, { channel: '#ops', threadTs: '171234.0001' },
  { threadTs: '1.2' }, { actionUrl: '/security', expiresInHours: 5 }, { expiresInHours: 0.001 },
  { expiresInHours: 0 }, { channel: '#override' }
];
const factoryOptionsPool = [
  {}, { maxPerHour: 1 }, { maxPerHour: 0 }, { maxPerHour: 2, defaultLocale: 'es-ES' },
  { from: 'alerts@example.com', replyTo: 'help@example.com', unsubscribeBaseUrl: 'https://x.test/u' },
  { segmentLength: 40, senderId: 'ACME' }, { segmentLength: 1 },
  { defaultWorkspace: 'product', defaultChannel: '#team' },
  { defaultIcon: 'star', defaultAction: '/inbox', channel: 'ignored' },
  { templates: { a: 1 }, defaultSender: 'Someone' }
];
const transportKinds = ['logging', 'logging', 'logging', 'mutating', 'failing', 'none', 'nonFunction'];

function randomScenario() {
  const channel = pick(channels);
  const user = pick(users);
  const message = pick(messages);
  const preload = rand() < 0.3 && user && typeof user === 'object' && user.id
    ? [[`${channel}:${user.id}:${(message && message.category) || 'general'}`,
        [Date.parse('2026-01-02T02:30:00.000Z'), Date.parse('2026-01-02T01:00:00.000Z'), Date.parse('2026-01-02T03:00:00.000Z')]]]
    : [];
  return {
    channel, user, message, preload,
    sendOptions: pick(sendOptionsPool),
    factoryOptions: pick(factoryOptionsPool),
    transportKind: pick(transportKinds),
    repeats: 1 + Math.floor(rand() * 4),
    realClock: rand() < 0.05,
    clockStart: rand() < 0.3 ? 0 : undefined
  };
}

async function compare(s, label) {
  const before = await run(original, s);
  const after = await run(refactored, s);
  try {
    assert.deepStrictEqual(after, before);
  } catch (error) {
    console.error(`MISMATCH in ${label}: ${JSON.stringify(s)}`);
    throw error;
  }
  return before;
}

async function main() {
  const tally = { sent: 0, throttled: 0, errors: new Set() };
  const iterations = Number(process.argv[3] || 5000);
  for (let i = 0; i < iterations; i++) {
    for (const o of (await compare(randomScenario(), `random #${i}`)).outcomes) {
      if (o.error) tally.errors.add(o.error.message);
      else tally[o.ok.status]++;
    }
  }

  let exhaustive = 0;
  for (const channel of channels) {
    for (const message of messages) {
      for (const sendOptions of sendOptionsPool) {
        for (const factoryOptions of factoryOptionsPool) {
          for (const clockStart of [undefined, 0]) {
            await compare({ channel, user: users[0], message, sendOptions, factoryOptions, transportKind: 'logging', repeats: 3, preload: [], realClock: false, clockStart }, `exhaustive ${channel}`);
            exhaustive++;
          }
        }
      }
    }
  }

  assert.deepEqual(Object.keys(refactored.registry), Object.keys(original.registry));
  assert.deepEqual(Object.keys(refactored.createAllNotifiers({})), Object.keys(original.createAllNotifiers({})));
  for (const bad of ['fax', '', undefined, null, 42, 'EMAIL']) {
    const expected = { name: 'TypeError', message: `unknown notification channel: ${bad}` };
    assert.throws(() => original.createNotifier(bad), expected);
    assert.throws(() => refactored.createNotifier(bad), expected);
  }
  for (const key of ['toString', 'constructor', '__proto__', 'hasOwnProperty']) {
    assert.throws(() => refactored.createNotifier(key), { name: 'TypeError', message: `unknown notification channel: ${key}` });
  }
  const all = refactored.createAllNotifiers({});
  assert.notEqual(all.email.throttleStore, all.sms.throttleStore);
  assert.notEqual(all.email.transport, all.sms.transport);
  const shared = new Map();
  const both = refactored.createAllNotifiers({ throttleStore: shared });
  assert.equal(both.email.throttleStore, shared);
  assert.equal(both.inapp.throttleStore, shared);

  const EmailNotifier = require(path.join(repo, 'src/notifications/EmailNotifier.js'));
  const viaNew = new EmailNotifier({ transport: { email: async () => {} } });
  assert.equal((await viaNew.send({ id: 'x', email: 'x@example.com' }, { title: 't', body: 'b' })).status, 'sent');
  const { send } = refactored.createNotifier('inapp', { transport: { inapp: async () => {} } });
  assert.equal((await send({ id: 'd' }, { title: 't', body: 'b' })).status, 'sent');
  const mutable = refactored.createNotifier('sms', { transport: { sms: async () => {} }, maxPerHour: 5 });
  mutable.maxPerHour = 1;
  await mutable.send({ id: 'm', phone: '+15551234567' }, { title: 't', body: 'b' });
  assert.equal((await mutable.send({ id: 'm', phone: '+15551234567' }, { title: 't', body: 'b' })).status, 'throttled');

  console.log(`random=${iterations} exhaustive=${exhaustive} sent=${tally.sent} throttled=${tally.throttled} distinctErrors=${tally.errors.size}`);
  console.log('OK: current implementation matches the base-commit implementation');
}

main().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

